<?php
$d = $dashboardSummary ?? [];
$show = $show ?? [];
$money = static fn($v): string => number_format((float)$v, 0);
$currency = trim((string)($institute['currency_symbol'] ?? $institute['currency'] ?? 'PKR')) ?: 'PKR';
$fee = $d['fee'] ?? ['total'=>0,'paid'=>0,'remaining'=>0];
$feePercent = (float)$fee['total'] > 0 ? min(100, round(((float)$fee['paid'] / (float)$fee['total']) * 100)) : 0;
$attendanceTotal = (int)($d['studentsMarked'] ?? 0);
$attendancePercent = $attendanceTotal > 0 ? round(((int)$d['present'] / $attendanceTotal) * 100) : 0;
$staffPercent = (int)($d['employees'] ?? 0) > 0 ? round(((int)($d['staffPresent'] ?? 0) / (int)$d['employees']) * 100) : 0;
$esc = static fn($v): string => htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');

$showStudents   = !empty($show['students']);
$showEmployees  = !empty($show['employees']);
$showFinance    = !empty($show['finance']);
$showFees       = !empty($show['fees']);
$showAttendance = !empty($show['attendance']);
$showClasses    = !empty($show['classes']);
$showStaffAttendance = $showEmployees && $showAttendance;

$hasKpis = $showStudents || $showEmployees || $showFinance;
$hasProgress = $showAttendance || $showStaffAttendance || $showFees;
$hasAnalytics = $showFinance || $showClasses || $showFees;
// A user with a single narrow grant (live classes, say) legitimately sees no institute metrics.
// They still get the workspace shell, so the dashboard must read as a welcome rather than a fault.
$hasMetrics = $hasKpis || $hasAnalytics || $hasProgress;
?>
<main class="main" id="dashboard"><div class="main__inner section-stack">
<div class="page-heading"><div><h1>Dashboard</h1><p><?= $esc(date('l, j F Y')) ?> · Academic year <?= $esc(date('Y')) ?>–<?= $esc((int)date('Y') + 1) ?></p></div><?php if (can('*')): ?><button class="btn btn--secondary" type="button" data-dashboard-refresh><i data-lucide="refresh-cw"></i>Refresh dashboard</button><?php endif; ?></div>
<?php if ($hasKpis): ?>
<div class="kpi-toolbar"><button class="btn btn--secondary" type="button" data-kpi-toggle aria-pressed="false" aria-controls="dashboardKpis"><i data-lucide="eye"></i><span>Show stats</span></button></div>
<section class="kpi-grid kpi-grid--hidden" id="dashboardKpis" aria-label="Institute key metrics">
<?php if ($showStudents): ?><article class="dashboard-card kpi-card"><div class="kpi-card__top"><span class="kpi-card__icon"><i data-lucide="users-round"></i></span></div><p class="kpi-card__label">Total Students</p><strong class="kpi-card__value"><?= $esc($d['students'] ?? 0) ?></strong><p class="kpi-card__meta">Active enrolments</p></article><?php endif; ?>
<?php if ($showEmployees): ?><article class="dashboard-card kpi-card"><div class="kpi-card__top"><span class="kpi-card__icon"><i data-lucide="briefcase-business"></i></span></div><p class="kpi-card__label">Total Employees</p><strong class="kpi-card__value"><?= $esc($d['employees'] ?? 0) ?></strong><p class="kpi-card__meta">Active staff members</p></article><?php endif; ?>
<?php if ($showFinance): ?><article class="dashboard-card kpi-card"><div class="kpi-card__top"><span class="kpi-card__icon"><i data-lucide="circle-dollar-sign"></i></span></div><p class="kpi-card__label">Revenue</p><strong class="kpi-card__value"><?= $esc($currency) ?> <?= $money($d['revenue'] ?? 0) ?></strong><p class="kpi-card__meta">This month</p></article><?php endif; ?>
<?php if ($showFinance): ?><article class="dashboard-card kpi-card"><div class="kpi-card__top"><span class="kpi-card__icon"><i data-lucide="chart-spline"></i></span></div><p class="kpi-card__label">Total Profit</p><strong class="kpi-card__value"><?= $esc($currency) ?> <?= $money(($d['revenue'] ?? 0) - ($d['costs'] ?? 0)) ?></strong><p class="kpi-card__meta">Revenue less expenses</p></article><?php endif; ?>
</section>
<?php endif; ?>
<style>.kpi-toolbar{display:flex;justify-content:flex-end;margin-bottom:-8px}.kpi-grid--hidden .kpi-card__value{font-size:0!important}.kpi-grid--hidden .kpi-card__value::after{content:"••••••";font-size:28px;letter-spacing:2px}</style>
<script>
// Main stats start hidden on every load so figures are not exposed on a shared screen.
document.querySelector('[data-kpi-toggle]')?.addEventListener('click', function () {
  var grid = document.getElementById('dashboardKpis');
  var hidden = grid.classList.toggle('kpi-grid--hidden');
  this.setAttribute('aria-pressed', hidden ? 'false' : 'true');
  this.querySelector('span').textContent = hidden ? 'Show stats' : 'Hide stats';
  this.querySelector('i, svg').outerHTML = '<i data-lucide="' + (hidden ? 'eye' : 'eye-off') + '"></i>';
  if (window.lucide) window.lucide.createIcons({ attrs: { "stroke-width": 1.9 } });
});
</script>
<section class="analytics-grid" aria-label="Financial and academic analytics"><div class="analytics-column">
<section class="dashboard-card hero-card" aria-labelledby="welcomeTitle"><div class="hero-card__content"><div class="hero-card__eyebrow"><i data-lucide="badge-check"></i><?= can('*') ? 'Administrator account' : 'Staff workspace' ?></div><h2 id="welcomeTitle">Welcome<?= !empty(user()['name']) ? ', ' . $esc(explode(' ', trim((string)user()['name']))[0]) : '' ?></h2><p><?= $hasMetrics ? 'Manage your institute from one place. Your live numbers will appear here as records are added.' : 'Your workspace is ready. Use the menu on the left to open the areas your role has access to.' ?></p><?php if (can_open('/admin/settings/institute-profile')): ?><a class="btn btn--light" href="<?= url('/admin/settings/institute-profile') ?>"><i data-lucide="settings"></i>Open settings</a><?php endif; ?></div><div class="hero-card__art" aria-hidden="true"><div class="hero-stars"></div><div class="hero-sun"></div><svg class="hero-building" viewBox="0 0 180 130" fill="none"><path d="M22 51 90 13l68 38v66H22V51Z" fill="currentColor" opacity=".18"/><path d="M42 48h96v69H42z" fill="currentColor" opacity=".93"/><path d="M72 70h36v47H72z" fill="#7A1632" opacity=".82"/><path d="M54 64h11v16H54zm61 0h11v16h-11zM54 91h11v16H54zm61 0h11v16h-11z" fill="#D9A441"/><path d="M17 117h146" stroke="currentColor" stroke-width="5" stroke-linecap="round"/><path d="m32 49 58-33 58 33" stroke="currentColor" stroke-width="8" stroke-linecap="round" stroke-linejoin="round"/></svg></div></section>
<?php if ($showFinance): ?>
<article class="dashboard-card income-card"><header class="dashboard-card__header"><div><h2 class="dashboard-card__title">Income vs Expense</h2><p class="dashboard-card__subtitle">Financial performance over the last six months</p></div><select class="select-control" id="incomeRange" aria-label="Income chart range"><option value="6">Last 6 months</option><option value="3">Last 3 months</option></select></header><div class="dashboard-card__body"><?php if (array_sum($d['incomes'] ?? []) + array_sum($d['expenses'] ?? []) > 0): ?><div class="legend" aria-hidden="true"><span class="legend__item"><span class="legend__dot" style="background:#7A1632"></span>Income</span><span class="legend__item"><span class="legend__dot" style="background:#D9A0AF"></span>Expense</span></div><div class="chart-wrap"><canvas id="incomeExpenseChart" aria-label="Income and expense line chart" role="img"></canvas></div><?php else: ?><div class="empty-state"><div><span class="empty-state__icon"><i data-lucide="chart-no-axes-combined"></i></span><strong>No financial activity yet</strong><p>Add income or expense records to see trends here.</p></div></div><?php endif; ?></div></article>
<?php endif; ?>
<?php if ($showClasses): ?>
<article class="dashboard-card class-strength-card"><header class="dashboard-card__header"><div><h2 class="dashboard-card__title">Class-wise Student Strength</h2><p class="dashboard-card__subtitle">Enrolment distribution across current classes</p></div></header><div class="dashboard-card__body"><?php if (!empty($d['classes'])): ?><div class="chart-wrap chart-wrap--short"><canvas id="classStrengthChart" aria-label="Class-wise student strength bar chart" role="img"></canvas></div><?php else: ?><div class="empty-state"><div><span class="empty-state__icon"><i data-lucide="school"></i></span><strong>No classes configured yet</strong><p>Create a class to see student distribution.</p></div></div><?php endif; ?></div></article>
<?php endif; ?>
</div><div class="analytics-column">
<?php if ($showFees): ?>
<article class="dashboard-card fee-status-card"><header class="dashboard-card__header"><div><h2 class="dashboard-card__title">Fee Status</h2><p class="dashboard-card__subtitle">Current collection estimate</p></div></header><div class="dashboard-card__body"><?php if ((float)$fee['total'] > 0): ?><div class="fee-chart"><canvas id="feeStatusChart" aria-label="Fee collection doughnut chart" role="img"></canvas><div class="fee-chart__center"><strong><?= $feePercent ?>%</strong><span>Collected</span></div></div><div class="fee-stats"><div class="fee-stat"><span>Collections</span><strong><?= $esc($currency) ?> <?= $money($fee['paid']) ?></strong></div><div class="fee-stat"><span>Remaining</span><strong><?= $esc($currency) ?> <?= $money($fee['remaining']) ?></strong></div><div class="fee-stat"><span>Estimation</span><strong><?= $esc($currency) ?> <?= $money($fee['total']) ?></strong></div></div><?php else: ?><div class="empty-state"><div><span class="empty-state__icon"><i data-lucide="receipt"></i></span><strong>No fee invoices yet</strong><p>Fee collection will appear after invoices are issued.</p></div></div><?php endif; ?></div></article>
<?php endif; ?>
<?php if (can('*')): ?><article class="dashboard-card promo-card promo-card--sms"><span class="promo-card__icon"><i data-lucide="smartphone"></i></span><div class="promo-card__content"><h3>SMS Center</h3><p>Queue SMS for parents, students and staff, sent through the institute's Android SIM gateway.</p></div><a class="btn btn--primary" href="<?= e(url('/admin/sms')) ?>">Open SMS Center</a></article><?php endif; ?>
<?php if ($hasProgress): ?>
<article class="dashboard-card progress-card"><header class="dashboard-card__header"><div><h2 class="dashboard-card__title">Key Progress</h2><p class="dashboard-card__subtitle">Live operational targets</p></div></header><div class="dashboard-card__body"><div class="progress-list">
<?php if ($showAttendance): ?><div class="progress-row"><div class="progress-row__top"><span class="progress-row__icon"><i data-lucide="user-check"></i></span><span class="progress-row__copy"><strong>Today Present Students</strong><span><?= (int)($d['present'] ?? 0) ?> of <?= $attendanceTotal ?></span></span><span class="progress-row__value"><?= $attendancePercent ?>%</span></div><div class="progress-track"><div class="progress-fill" style="width:<?= $attendancePercent ?>%"></div></div></div><?php endif; ?>
<?php if ($showStaffAttendance): ?><div class="progress-row"><div class="progress-row__top"><span class="progress-row__icon"><i data-lucide="contact-round"></i></span><span class="progress-row__copy"><strong>Present Staff</strong><span><?= (int)($d['staffPresent'] ?? 0) ?> of <?= (int)($d['employees'] ?? 0) ?></span></span><span class="progress-row__value"><?= $staffPercent ?>%</span></div><div class="progress-track"><div class="progress-fill" style="width:<?= $staffPercent ?>%"></div></div></div><?php endif; ?>
<?php if ($showFees): ?><div class="progress-row"><div class="progress-row__top"><span class="progress-row__icon"><i data-lucide="receipt-text"></i></span><span class="progress-row__copy"><strong>Fee Collection Progress</strong><span><?= $esc($currency) ?> <?= $money($fee['paid']) ?> collected</span></span><span class="progress-row__value"><?= $feePercent ?>%</span></div><div class="progress-track"><div class="progress-fill" style="width:<?= $feePercent ?>%"></div></div></div><?php endif; ?>
</div></div></article>
<?php endif; ?>
</div></section>
<section class="activity-grid" aria-label="Daily institute activity">
<?php if ($showAttendance): ?><article class="dashboard-card mini-stat-card"><header class="dashboard-card__header"><div><h2 class="dashboard-card__title">Absent Students</h2><p class="dashboard-card__subtitle">Today</p></div><?php if (can_open('/admin/attendance/daily-report')): ?><a class="text-button" href="<?= e(url('/admin/attendance/daily-report?status=Absent')) ?>">View all</a><?php else: ?><span class="kpi-card__icon"><i data-lucide="user-x"></i></span><?php endif; ?></header><div class="dashboard-card__body"><?php if ($attendanceTotal): ?><strong class="mini-stat-card__number"><?= (int)($d['absent'] ?? 0) ?></strong><p class="mini-stat-card__meta">of <?= $attendanceTotal ?> students marked today</p><?php if (!empty($d['absentStudents'])): ?><div class="admission-list"><?php foreach ($d['absentStudents'] as $a): ?><div class="admission-row"><span class="admission-row__copy"><strong><?= $esc($a['student_name']) ?></strong><span><?= $esc((string)$a['class_name']) ?> · #<?= $esc($a['registration_no']) ?></span></span></div><?php endforeach; ?></div><?php endif; ?><?php else: ?><div class="empty-state"><div><span class="empty-state__icon"><i data-lucide="clipboard-list"></i></span><strong>Attendance not marked yet</strong><p>Records will appear once submitted.</p><?php if (can('attendance.manage')): ?><a class="btn btn--primary" href="<?= e(url('/admin/attendance/students?scope=all')) ?>">Mark attendance</a><?php endif; ?></div></div><?php endif; ?></div></article><?php endif; ?>
<?php if ($showStaffAttendance): ?><article class="dashboard-card mini-stat-card"><header class="dashboard-card__header"><div><h2 class="dashboard-card__title">Present Staff</h2><p class="dashboard-card__subtitle">Today</p></div><?php if (can_open('/admin/attendance/employees')): ?><a class="text-button" href="<?= e(url('/admin/attendance/employees')) ?>">View all</a><?php else: ?><span class="kpi-card__icon"><i data-lucide="contact-round"></i></span><?php endif; ?></header><div class="dashboard-card__body"><?php if (!(int)($d['employees'] ?? 0)): ?><div class="empty-state"><div><span class="empty-state__icon"><i data-lucide="clipboard-list"></i></span><strong>No employees yet</strong><p>Add staff to track attendance.</p></div></div><?php elseif (!(int)($d['staffMarked'] ?? 0)): ?><div class="empty-state"><div><span class="empty-state__icon"><i data-lucide="clipboard-list"></i></span><strong>Staff attendance not marked yet</strong><p>Mark today's staff attendance to see who is in.</p><?php if (can('attendance.manage')): ?><a class="btn btn--primary" href="<?= e(url('/admin/attendance/employees')) ?>">Mark attendance</a><?php endif; ?></div></div><?php else: ?><strong class="mini-stat-card__number"><?= (int)($d['staffPresent'] ?? 0) ?></strong><p class="mini-stat-card__meta"><?= $staffPercent ?>% of <?= (int)$d['employees'] ?> active employees</p><?php endif; ?></div></article><?php endif; ?>
<?php if ($showStudents): ?><article class="dashboard-card"><header class="dashboard-card__header"><div><h2 class="dashboard-card__title">New Admissions</h2><p class="dashboard-card__subtitle">This month</p></div><a class="text-button" href="<?= e(url('/admin/students')) ?>">View all</a></header><div class="dashboard-card__body"><div class="admission-list"><?php if (!empty($d['admissions'])): foreach ($d['admissions'] as $admission): $name=(string)$admission['student_name']; $initials=strtoupper(substr(preg_replace('/[^A-Za-z]/','',$name),0,2)); ?><div class="admission-row"><span class="avatar"><?= $esc($initials) ?></span><span class="admission-row__copy"><strong><?= $esc($name) ?></strong><span><?= $esc($admission['class_name']) ?> · #<?= $esc($admission['registration_no']) ?></span></span><time><?= $esc($admission['date_of_admission']) ?></time></div><?php endforeach; else: ?><div class="empty-state"><div><span class="empty-state__icon"><i data-lucide="user-plus"></i></span><strong>No new admissions this month</strong><p>New students will appear here after registration.</p></div></div><?php endif; ?></div></div></article><?php endif; ?>
